/* Map the logical LED number to its GPIO configuration.  The ALIENTEK
 * ATK-DNN647 drives both LEDs active-low (LED0=PG10, LED1=PE10), so
 * board_userled()/board_userled_all() invert the logical state.
 */

static const uint32_t g_ledcfg[BOARD_NLEDS] =
{
  GPIO_LED0,
  GPIO_LED1,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

uint32_t board_userled_initialize(void)
{
  int i;

  /* Configure the LED GPIOs as push-pull outputs, initially off */

  for (i = 0; i < BOARD_NLEDS; i++)
    {
      stm32n6_configgpio(g_ledcfg[i]);
    }

  return BOARD_NLEDS;
}

void board_userled(int led, bool ledon)
{
  if ((unsigned)led < BOARD_NLEDS)
    {
      /* LEDs are active-low on the ATK-DNN647 */

      stm32n6_gpiowrite(g_ledcfg[led], !ledon);
    }
}

void board_userled_all(uint32_t ledset)
{
  int i;

  for (i = 0; i < BOARD_NLEDS; i++)
    {
      stm32n6_gpiowrite(g_ledcfg[i], (ledset & (1 << i)) == 0);
    }
}

#endif /* !CONFIG_ARCH_LEDS */
```

