/**
 ******************************************************************************
 * @file    probe_risaf.c
 * @brief   RISAF 默认策略探针 — 判断 flash-boot 下 GPDMA1/DMA2D 写 SRAM 是否被拦截
 *
 * @usage   本文件用于 STM32N6 的 XIP 探针固件（基于正点原子 05_Serial 工程，
 *          该工程已验证可经预编译 FSBL 以 XIP 模式从 NOR Flash 启动）。
 *
 *          集成步骤：
 *            1. 把本文件加入 05_Serial 工程（Appli 部分）
 *            2. 在 main() 的外设初始化之后调用 probe_risaf_run()
 *            3. 用 CubeProgrammer + External Loader 把 appli.hex 烧到 0x70100400
 *            4. 切 Flash boot（BOOT1=0, BOOT0=0），复位，看串口输出
 *
 *          判定标准：
 *            - GPDMA1: PASS + DMA2D: PASS  → flash-boot 默认 RISAF 宽松，免自定义 FSBL
 *            - 任一 FAIL（SRAM 内容未被写入）→ 默认策略仍拦截总线主，必须自写 FSBL 授权 CID
 *
 * @note    本探针在 DEV boot 下已知 GPDMA1/DMA2D 写 SRAM 会被丢弃（参考工程 ADR-029/032）。
 *          目的是验证 flash-boot 分支是否不同。
 ******************************************************************************
 */

#include "main.h"
#include <stdio.h>
#include <string.h>

/* ---- 测试参数 ----------------------------------------------------------- */

#define PROBE_SRC_SIZE    128            /* 单次搬运字节数 */
#define PROBE_FILL_PAT    0xA5A5A5A5UL   /* DMA2D 填充颜色 */

/* 源数据放在 flash（XIP 可读），目标放 SRAM（写失败=被 RISAF 拦截） */
static const uint8_t probe_src[PROBE_SRC_SIZE] = {
  0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
  0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF, 0x00, 0x99,
};
static uint8_t probe_dst_gpdma[PROBE_SRC_SIZE] __attribute__((aligned(4)));
static uint8_t probe_dst_dma2d[256] __attribute__((aligned(4)));

/* ---- 私有句柄 ----------------------------------------------------------- */

DMA_HandleTypeDef hdma_gpdma1_ch0;
DMA2D_HandleTypeDef hdma2d;

/* -------------------------------------------------------------------------- */
/*  GPDMA1 测试：内存到内存搬运，然后校验目标                                  */
/* -------------------------------------------------------------------------- */
static int probe_gpdma_test(void)
{
  uint32_t i;
  int ok = 1;

  memset(probe_dst_gpdma, 0x00, sizeof(probe_dst_gpdma));

  /* 使能 GPDMA1 时钟（05_Serial 工程里 HAL_DMA_Init 的 MspInit 也会做，
     这里显式保证一次） */
  __HAL_RCC_GPDMA1_CLK_ENABLE();

  /* 配置 GPDMA1_Channel0：内存到内存 */
  hdma_gpdma1_ch0.Instance                 = GPDMA1_Channel0;
  hdma_gpdma1_ch0.Init.Request             = DMA_REQUEST_MEM2MEM;
  hdma_gpdma1_ch0.Init.BlkHWRequest        = DMA_BREQ_SINGLE_BURST;
  hdma_gpdma1_ch0.Init.Direction           = DMA_MEMORY_TO_MEMORY;
  hdma_gpdma1_ch0.Init.SrcInc              = DMA_SINC_INCREMENTED;
  hdma_gpdma1_ch0.Init.DestInc             = DMA_DINC_INCREMENTED;
  hdma_gpdma1_ch0.Init.SrcDataWidth        = DMA_SDATAALIGN_BYTE;
  hdma_gpdma1_ch0.Init.DestDataWidth       = DMA_DDATAALIGN_BYTE;
  hdma_gpdma1_ch0.Init.Priority            = DMA_PRIORITY_HIGH;
  hdma_gpdma1_ch0.Init.SrcBurstLength      = 1;
  hdma_gpdma1_ch0.Init.DestBurstLength     = 1;
  hdma_gpdma1_ch0.Init.TransferAllocatedPort = DMA_ALLOCATED_PORT0;
  hdma_gpdma1_ch0.Init.TransferEventMode   = DMA_TCEM_BLOCK_TRANSFER;
  hdma_gpdma1_ch0.Init.Mode                = DMA_NORMAL;

  if (HAL_DMA_Init(&hdma_gpdma1_ch0) != HAL_OK)
    {
      printf("[GPDMA1] init FAILED\r\n");
      return -1;
    }

  /* 启动搬运：flash 源 -> SRAM 目标 */
  if (HAL_DMA_Start(&hdma_gpdma1_ch0,
                    (uint32_t)probe_src,
                    (uint32_t)probe_dst_gpdma,
                    PROBE_SRC_SIZE) != HAL_OK)
    {
      printf("[GPDMA1] start FAILED\r\n");
      return -1;
    }

  if (HAL_DMA_PollForTransfer(&hdma_gpdma1_ch0, HAL_DMA_FULL_TRANSFER,
                              1000) != HAL_OK)
    {
      printf("[GPDMA1] poll timeout/error\r\n");
      return -1;
    }

  /* 校验：若 RISAF 拦截，目标仍全 0 */
  for (i = 0; i < PROBE_SRC_SIZE; i++)
    {
      if (probe_dst_gpdma[i] != probe_src[i])
        {
          ok = 0;
          break;
        }
    }

  printf("[GPDMA1] write SRAM: %s (first byte 0x%02X)\r\n",
         ok ? "PASS" : "FAIL(dropped)", probe_dst_gpdma[0]);
  return ok ? 0 : 1;
}

/* -------------------------------------------------------------------------- */
/*  DMA2D 测试：寄存器到内存填充，然后校验                                     */
/* -------------------------------------------------------------------------- */
static int probe_dma2d_test(void)
{
  uint32_t i;
  int ok = 1;
  uint32_t *p;

  memset(probe_dst_dma2d, 0x00, sizeof(probe_dst_dma2d));

  __HAL_RCC_DMA2D_CLK_ENABLE();

  /* DMA2D 填充模式：R2M（寄存器到内存）*/
  hdma2d.Instance                 = DMA2D;
  hdma2d.Init.Mode                = DMA2D_R2M;
  hdma2d.Init.ColorMode           = DMA2D_ARGB8888;
  hdma2d.Init.OutputOffset        = 0;
  hdma2d.Init.AlphaInverted       = DMA2D_REGULAR_ALPHA;
  hdma2d.Init.RbAlpha             = 0;

  if (HAL_DMA2D_Init(&hdma2d) != HAL_OK)
    {
      printf("[DMA2D] init FAILED\r\n");
      return -1;
    }

  /* 填充 64x1 像素（256B） */
  if (HAL_DMA2D_Start(&hdma2d, PROBE_FILL_PAT,
                      (uint32_t)probe_dst_dma2d, 64, 1) != HAL_OK)
    {
      printf("[DMA2D] start FAILED\r\n");
      return -1;
    }

  if (HAL_DMA2D_PollForTransfer(&hdma2d, 1000) != HAL_OK)
    {
      printf("[DMA2D] poll timeout/error\r\n");
      return -1;
    }

  /* 校验：ARGB8888 每像素 4 字节 */
  p = (uint32_t *)probe_dst_dma2d;
  for (i = 0; i < 64; i++)
    {
      if (p[i] != PROBE_FILL_PAT)
        {
          ok = 0;
          break;
        }
    }

  printf("[DMA2D]  fill SRAM: %s (first px 0x%08lX)\r\n",
         ok ? "PASS" : "FAIL(dropped)", (unsigned long)p[0]);
  return ok ? 0 : 1;
}

/* -------------------------------------------------------------------------- */
/*  探针入口                                                                  */
/* -------------------------------------------------------------------------- */
void probe_risaf_run(void)
{
  int gpdma_ok;
  int dma2d_ok;

  printf("\r\n=== RISAF probe (flash-boot) ===\r\n");

  gpdma_ok = probe_gpdma_test();
  dma2d_ok = probe_dma2d_test();

  printf("=== Result: GPDMA1 %s / DMA2D %s ===\r\n",
         (gpdma_ok == 0) ? "PASS" : "FAIL",
         (dma2d_ok == 0) ? "PASS" : "FAIL");

  if (gpdma_ok == 0 && dma2d_ok == 0)
    {
      printf(">>> flash-boot RISAF is PERMISSIVE: no custom FSBL needed\r\n");
    }
  else
    {
      printf(">>> flash-boot RISAF still BLOCKS bus masters: custom FSBL (RISAF CID grant) required\r\n");
    }
}

