  memset(probe_dst_dma2d, 0x00, sizeof(probe_dst_dma2d));

  __HAL_RCC_DMA2D_CLK_ENABLE();

  /* R2M 填充：CR.MODE=0b11，输出 ARGB8888，无偏移，颜色=图案 */
  DMA2D->CR     = (DMA2D_CR_MODE_1 | DMA2D_CR_MODE_0);  /* R2M */
  DMA2D->OPFCCR = 0;                                    /* ARGB8888 */
  DMA2D->OOR    = 0;                                    /* 无输出偏移 */
  DMA2D->OCOLR  = PROBE_FILL_PAT;                       /* 填充颜色 */
  DMA2D->NLR    = ((uint32_t)64 << 16) | 1;             /* PL=64 像素, NL=1 行 */

  /* 启动 */
  DMA2D->CR |= DMA2D_CR_START;

  /* 等待传输完成 TCIF */
  timeout = 1000000;
  while (timeout-- > 0)
    {
      if (DMA2D->ISR & DMA2D_ISR_TCIF)
        {
          DMA2D->IFCR = DMA2D_IFCR_CTCIF;
          break;
        }
    }

  if (timeout == 0)
    {
      printf("[DMA2D] timeout\r\n");
      return -1;
    }

  /* 校验：ARGB8888 每像素 4 字节；若 RISAF 拦截，目标仍全 0 */
  p = (uint32_t *)probe_dst_dma2d;
  for (i = 0; i < 64; i++)
    {
      if (p[i] != PROBE_FILL_PAT)
        {
          ok = 0;
          break;
        }
    }

  printf("[DMA2D]  fill SRAM: %s (first px 0x%08lX)\r\n",
         ok ? "PASS" : "FAIL(dropped)", (unsigned long)p[0]);
  return ok ? 0 : 1;
}

