/* Private user code ---------------------------------------------------------*/
/* USER CODE BEGIN 0 */

/* Custom RIF setup: unlock the DMA-capable bus masters (DMA2D/GPDMA1/NPU/GPU2D)
 * so they can read/write the firmware SRAM after boot.  The stock (prebuilt)
 * FSBL does not program RIF at all, which leaves every non-CPU master blocked
 * from SRAM (verified by the RISAF probe on real HW, both DEV and flash boot).
 */
static void RIF_Config(void)
{
  RIMC_MasterConfig_t rimc_cfg;
  RISAF_BaseRegionConfig_t risaf_cfg;
  uint32_t i;

  /* Enable the RIFSC and GPDMA1 clocks before touching RIF registers. */
  __HAL_RCC_RIFSC_CLK_ENABLE();
  __HAL_RCC_GPDMA1_CLK_ENABLE();

  /* 1) RIMC: give DMA2D (idx 8), GPU2D (idx 7) and NPU (idx 1) CID0 with
   *    secure+privileged attributes.  GPDMA1 has no RIMC entry; its CID is
   *    set per-channel via CCIDCFGR (step 2).
   */
  rimc_cfg.MasterCID = RIF_CID_0;
  rimc_cfg.SecPriv   = RIF_ATTRIBUTE_SEC | RIF_ATTRIBUTE_PRIV;
  HAL_RIF_RIMC_ConfigMasterAttributes(RIF_MASTER_INDEX_DMA2D, &rimc_cfg);
#if defined(RIF_MASTER_INDEX_GPU2D)
  HAL_RIF_RIMC_ConfigMasterAttributes(RIF_MASTER_INDEX_GPU2D, &rimc_cfg);
#endif
#if defined(RIF_MASTER_INDEX_NPU)
  HAL_RIF_RIMC_ConfigMasterAttributes(RIF_MASTER_INDEX_NPU, &rimc_cfg);
#endif

  /* 2) GPDMA1: static CID0 + isolation enable on all 8 channels. */
  for (i = 0U; i < 8U; i++)
    {
      ((DMA_Channel_TypeDef *)(GPDMA1_Channel0_BASE + (i * 0x80U)))->CCIDCFGR =
        DMA_CCIDCFGR_SCID_0 | DMA_CCIDCFGR_CFEN;
    }

  /* 3) RISAF: open the SRAM/AXISRAM address windows to every CID, so any
   *    master can read/write firmware memory.  Start/End are offsets from
   *    the base of each protected address space.
   */
  risaf_cfg.Filtering      = RISAF_FILTER_ENABLE;
  risaf_cfg.Secure         = RIF_ATTRIBUTE_NSEC; /* non-secure: most open */
  risaf_cfg.PrivWhitelist  = RIF_CID_MASK;
  risaf_cfg.ReadWhitelist  = RIF_CID_MASK;
  risaf_cfg.WriteWhitelist = RIF_CID_MASK;

  /* RISAF7 -> FLEXMEM/AXISRAM where the firmware runs (0x34000400). */
  risaf_cfg.StartAddress = 0x0U;
  risaf_cfg.EndAddress   = RISAF7_LIMIT_ADDRESS_SPACE_SIZE;
  HAL_RIF_RISAF_ConfigBaseRegion(RISAF7, RISAF_REGION_0, &risaf_cfg);

  /* RISAF1 -> system space 0x00000000-0x3FFFFFFF (SRAM1-5 + AXISRAM aliases). */
  risaf_cfg.StartAddress = 0x0U;
  risaf_cfg.EndAddress   = RISAF1_LIMIT_ADDRESS_SPACE_SIZE;
  HAL_RIF_RISAF_ConfigBaseRegion(RISAF1, RISAF_REGION_0, &risaf_cfg);

#if defined(RISAF4)
  /* RISAF4/5/6 -> large AXISRAM windows (present when NPU is fitted). */
  risaf_cfg.StartAddress = 0x0U;
  risaf_cfg.EndAddress   = 0x3FFFFFFFU;
  HAL_RIF_RISAF_ConfigBaseRegion(RISAF4, RISAF_REGION_0, &risaf_cfg);
  HAL_RIF_RISAF_ConfigBaseRegion(RISAF5, RISAF_REGION_0, &risaf_cfg);
  HAL_RIF_RISAF_ConfigBaseRegion(RISAF6, RISAF_REGION_0, &risaf_cfg);
#endif
}

/* USER CODE END 0 */
```

